sigjmp_buf env;
#define JUMP_VAL 42

// Signal handler
void jump_handler(int sig) {
    if (sig == SIGALRM) {
        // Jumps back to sigsetjmp call site
        siglongjmp(env, JUMP_VAL);
    }
}

// Main logic entry
int ret = sigsetjmp(env, 1); // 1 = save signal mask

if (ret == 0) {
    // Normal flow: Initial setup
    // Set up sigaction for jump_handler
} else if (ret == JUMP_VAL) {
    // Flow resumed via siglongjmp
    // Signal mask is restored to state when sigsetjmp was called
}

// Note: Use '1' in sigsetjmp to save/restore the signal mask.
